import sys, json, base64, csv, io, ipaddress, hashlib
sys.path.insert(0,'/workspace/tmp'); sys.path.insert(0,'/workspace/submission')
import t_random, ref
from harness import run
HEADER=t_random.HEADER

def lookup_of(job):
    leases={l['id']:l for l in job['leases']}
    lookup={}
    for lid in sorted(leases):
        L=leases[lid]
        net=ipaddress.IPv6Network(L['prefix'])
        for sub in sorted(L['subnets']):
            n64=int(net.network_address)+(sub<<64)
            canon=str(ipaddress.IPv6Network((n64,64)))
            d=hashlib.sha256((job['seed']+'\n'+lid+'\n'+canon).encode()).digest()
            iid=int.from_bytes(d[:8],'big')|(1<<63)
            for tag,val,isc in [('c',iid,True)]+[(f'i{i}',i,False) for i in range(1,L['low_count']+1)]:
                lookup[(lid,(sub,isc,0 if isc else val))]=(n64+val,isc)
    return leases,lookup

for seed in (0,10):
    job=t_random.build(seed)
    mine=run(job); theirs=ref.run(job)
    a=set(map(tuple,mine['rejected'])); b=set(map(tuple,theirs['rejected']))
    print('seed',seed,'only mine',sorted(a-b),'only ref',sorted(b-a))
    leases,lookup=lookup_of(job)
    services={s['id']:s['kind'] for s in job['services']}
    for ci,cap in enumerate(job['captures']):
        raw=b''.join(base64.b64decode(c) for c in cap['chunks'])
        if cap['encoding']=='zstd':
            import zstandard as zstd
            raw=zstd.ZstdDecompressor().stream_reader(io.BytesIO(raw),read_across_frames=True).read()
        recs=list(csv.reader(io.StringIO(raw.decode('utf-8'),newline=''),strict=True))
        for ordinal,values in enumerate(recs[1:]):
            if (ci,ordinal) in (a-b)|(b-a):
                print('seed',seed,'cap',ci,'ord',ordinal,values)
                print('   ref ->',ref.parse(values,leases,services,lookup))
                print('   lease interval', [(l['id'],l['start'],l['end'],l['subnets'],l['low_count']) for l in job['leases'] if l['id']==values[5]])
PYEOF
